pub fn field_summary_for_type(
    base_type: Rc<Node>,
    env: Rc<TypeEnv>,
    field: String,
) -> Option<Rc<FieldSummary>> {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        let resolved = resolve_scrutinee_type_node(env.clone(), base_type.clone());
        let normed = crate::v1_compiler_infer_types::normalize_access_type_node(resolved.clone());
        let normed_opt = (normed.return_cardinality.clone() == Cardinality::CardOptional);
        if ((field.clone() == "value".to_string()) && normed_opt.clone()) {
            Some(Rc::new(FieldSummary {
                access_style: FieldAccessStyle::OptionalUnwrap,
                value_shape: FieldValueShape::PlainValue,
            }))
        } else {
            if normed_opt.clone() {
                {
                    let inner = crate::v1_std_core::with_required_cardinality(normed.clone());
                    match field_summary_for_type(inner.clone(), env.clone(), field.clone()) {
                        Some(inner_summary) => Some(Rc::new(FieldSummary {
                            access_style: inner_summary.access_style.clone(),
                            value_shape: FieldValueShape::OptionalValue,
                        })),
                        None => None,
                    }
                }
            } else {
                {
                    let no_structure = (resolved.connective.clone() == Connective::NoConnective);
                    if no_structure.clone() {
                        None
                    } else {
                        {
                            let is_product = (resolved.connective.clone() == Connective::Conj);
                            if is_product.clone() {
                                v1_rt::map_get(&crate::v1_compiler_infer_emit_info::build_struct_field_summaries(resolved.clone(), env.source_indices.clone()), field.clone())
                            } else {
                                v1_rt::map_get(
                                    &crate::v1_compiler_infer_emit_info::build_enum_field_summaries(
                                        resolved.children.clone(),
                                        env.source_indices.clone(),
                                    ),
                                    field.clone(),
                                )
                            }
                        }
                    }
                }
            }
        }
    })
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct MethodFieldResult {
    pub field_node: Rc<Node>,
    pub result_type: Rc<Node>,
    pub size_effect: Option<CollectionSizeEffect>,
    pub cost_shape: Option<CostShape>,
    pub algebra_template: Option<Rc<AlgebraFieldTemplate>>,
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct StructuralMethodLookup {
    pub resolution: Option<Rc<MethodFieldResult>>,
    pub kernel_diagnostics: Rc<Vec<Rc<ErrorNode>>>,
}

pub fn product_field_result_type(field: Rc<Node>) -> Option<Rc<Node>> {
    match field.inferred.clone().as_deref().cloned() {
        Some(InferredNode::Resolved { node: rt, .. }) => {
            if ((rt.params.clone().len() as i64) > 0) {
                match rt.inferred.clone().as_deref().cloned() {
                    Some(InferredNode::Resolved {
                        node: return_type, ..
                    }) => Some(return_type.clone()),
                    _ => Some(rt.clone()),
                }
            } else {
                Some(rt.clone())
            }
        }
        _ => None,
    }
}

pub fn map_lookup_result_type(
    product: Rc<Node>,
    field: Rc<Node>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Option<Rc<Node>> {
    if (crate::v1_std_core::authored_name_at(source_indices.clone(), product.clone())
        == "Map".to_string())
    {
        match product_field_result_type(field.clone()) {
            Some(raw) => {
                if (raw.return_cardinality.clone() == Cardinality::CardOptional) {
                    Some(raw.clone())
                } else {
                    Some(crate::v1_std_core::with_optional_cardinality(raw.clone()))
                }
            }
            None => None,
        }
    } else {
        None
    }
}

pub fn lookup_field_in_product(
    product: Rc<Node>,
    method_name: String,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Option<Rc<MethodFieldResult>> {
    {
        let matching = Rc::new({
            let mut __result = Vec::new();
            for c in product.children.clone().iter().cloned() {
                if (crate::v1_std_core::authored_name_at(source_indices.clone(), c.clone())
                    == method_name.clone())
                {
                    __result.push(c);
                }
            }
            __result
        });
        match matching.clone().first().cloned() {
            Some(field) => match if (method_name.clone() == "lookup".to_string()) {
                map_lookup_result_type(product.clone(), field.clone(), source_indices.clone())
            } else {
                None
            } {
                Some(lookup_rt) => Some(Rc::new(MethodFieldResult {
                    field_node: field.clone(),
                    result_type: lookup_rt.clone(),
                    size_effect: None,
                    cost_shape: None,
                    algebra_template: None,
                })),
                None => match product_field_result_type(field.clone()) {
                    Some(rt) => Some(Rc::new(MethodFieldResult {
                        field_node: field.clone(),
                        result_type: rt.clone(),
                        size_effect: None,
                        cost_shape: None,
                        algebra_template: None,
                    })),
                    None => None,
                },
            },
            None => None,
        }
    }
}

pub fn lookup_structural_method(
    receiver_type: Rc<Node>,
    method_name: String,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Rc<StructuralMethodLookup> {
    {
        let is_product = (receiver_type.connective.clone() == Connective::Conj);
        if is_product.clone() {
            {
                let direct = lookup_field_in_product(
                    receiver_type.clone(),
                    method_name.clone(),
                    source_indices.clone(),
                );
                Rc::new(StructuralMethodLookup {
                    resolution: direct.clone(),
                    kernel_diagnostics: Rc::new(vec![]),
                })
            }
        } else {
            {
                let enriched = crate::v1_compiler_infer_types::enrich_kernel_type(
                    crate::v1_std_core::authored_name_at(
                        source_indices.clone(),
                        receiver_type.clone(),
                    ),
                    receiver_type.clone(),
                    source_indices.clone(),
                );
                if ((enriched.ty.clone().connective.clone() == Connective::Conj)
                    && ((enriched.ty.clone().children.clone().len() as i64) > 0))
                {
                    {
                        let base_result = lookup_field_in_product(
                            enriched.ty.clone(),
                            method_name.clone(),
                            source_indices.clone(),
                        );
                        match base_result.clone() {
                            Some(mfr) => {
                                let profile = crate::v1_compiler_infer_types::kernel_profile_lookup(
                                    crate::v1_std_core::authored_name_at(
                                        source_indices.clone(),
                                        receiver_type.clone(),
                                    ),
                                );
                                let template_match = match profile.clone() {
                                    Some(p) => {
                                        let templates =
                                            crate::std_algebra::algebra_templates_for_profile(
                                                p.clone(),
                                            );
                                        Rc::new({
                                            let mut __result = Vec::new();
                                            for t in templates.iter().cloned() {
                                                if (t.name.clone() == method_name.clone()) {
                                                    __result.push(t);
                                                }
                                            }
                                            __result
                                        })
                                        .first()
                                        .cloned()
                                    }
                                    None => None,
                                };
                                let resolution = match template_match.clone() {
                                    Some(t) => Some(Rc::new(MethodFieldResult {
                                        field_node: mfr.field_node.clone(),
                                        result_type: mfr.result_type.clone(),
                                        size_effect: t.size_effect.clone(),
                                        cost_shape: t.cost_shape.clone(),
                                        algebra_template: Some(t.clone()),
                                    })),
                                    None => base_result.clone(),
                                };
                                Rc::new(StructuralMethodLookup {
                                    resolution: resolution.clone(),
                                    kernel_diagnostics: enriched.diagnostics.clone(),
                                })
                            }
                            None => Rc::new(StructuralMethodLookup {
                                resolution: None,
                                kernel_diagnostics: enriched.diagnostics.clone(),
                            }),
                        }
                    }
                } else {
                    Rc::new(StructuralMethodLookup {
                        resolution: None,
                        kernel_diagnostics: enriched.diagnostics.clone(),
                    })
                }
            }
        }
    }
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum DeclaredArgContract {
    ContractKnown { types: Rc<Vec<Rc<Node>>> },
    MethodUnresolved,
    ContractUnavailable,
}
impl DeclaredArgContract {
    pub fn types(&self) -> Rc<Vec<Rc<Node>>> {
        match self {
            DeclaredArgContract::ContractKnown { types: __val, .. } => __val.clone(),
            DeclaredArgContract::MethodUnresolved => panic!("no types on unit variant"),
            DeclaredArgContract::ContractUnavailable => panic!("no types on unit variant"),
        }
    }
}

pub fn declared_arg_types_for_method(
    receiver_type: Rc<Node>,
    method_name: String,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
    expand_field_type: impl Fn(Rc<Node>) -> Rc<Node> + Clone,
) -> Rc<DeclaredArgContract> {
    {
        let lookup = lookup_structural_method(
            receiver_type.clone(),
            method_name.clone(),
            source_indices.clone(),
        );
        match lookup.resolution.clone() {
            None => Rc::new(DeclaredArgContract::MethodUnresolved),
            Some(mfr) => match mfr.algebra_template.clone() {
                Some(t) => {
                    let first_is_self = match t.param_types.clone().first().cloned() {
                        Some(tp) => match (*tp.clone()).clone() {
                            AlgebraTypeTemplate::ReceiverSelf => true,
                            _ => false,
                        },
                        None => false,
                    };
                    let non_receiver_templates = if first_is_self.clone() {
                        Rc::new(
                            t.param_types
                                .clone()
                                .iter()
                                .cloned()
                                .skip(1 as usize)
                                .collect::<Vec<_>>(),
                        )
                    } else {
                        t.param_types.clone()
                    };
                    Rc::new(DeclaredArgContract::ContractKnown {
                        types: Rc::new({
                            let mut __result = Vec::new();
                            for tp in non_receiver_templates.iter().cloned() {
                                __result.push(
                                    crate::v1_compiler_infer_types::instantiate_algebra_type(
                                        tp.clone(),
                                        receiver_type.clone(),
                                        source_indices.clone(),
                                    )
                                    .ty
                                    .clone(),
                                );
                            }
                            __result
                        }),
                    })
                }
                None => match mfr.field_node.clone().inferred.clone().as_deref().cloned() {
                    Some(InferredNode::Resolved { node: callable, .. }) => {
                        let expanded = if ((callable.params.clone().len() as i64) > 0) {
                            callable.clone()
                        } else {
                            expand_field_type(callable.clone())
                        };
                        if ((expanded.params.clone().len() as i64) > 0) {
                            Rc::new(DeclaredArgContract::ContractKnown {
                                types: Rc::new({
                                    let mut __result = Vec::new();
                                    for p in expanded.params.clone().iter().cloned() {
                                        __result.push(crate::v1_std_core::param_node_type_expr(
                                            p.clone(),
                                        ));
                                    }
                                    __result
                                }),
                            })
                        } else {
                            Rc::new(DeclaredArgContract::ContractUnavailable)
                        }
                    }
                    _ => Rc::new(DeclaredArgContract::ContractUnavailable),
                },
            },
        }
    }
}

pub fn resolve_known_method_node(
    receiver: Rc<Node>,
    receiver_type: Rc<Node>,
    method_name: String,
    fold_accumulator_type: Option<Rc<Node>>,
    service_registry: Rc<HashMap<String, Rc<Vec<Rc<OpEntry>>>>>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Rc<KnownMethodResolution> {
    {
        let tier0 = lookup_structural_method(
            receiver_type.clone(),
            method_name.clone(),
            source_indices.clone(),
        );
        match tier0.resolution.clone() {
            Some(mfr) => {
                let semantics = Rc::new(MethodSemantics::AlgebraMethodSemantics {
                    method_def: mfr.field_node.clone(),
                    fold_accumulator_type: fold_accumulator_type.clone(),
                    size_effect: mfr.size_effect.clone(),
                    cost_shape: mfr.cost_shape.clone(),
                    algebra_template: mfr.algebra_template.clone(),
                });
                Rc::new(KnownMethodResolution {
                    semantics: Some(semantics.clone()),
                    result_type: Some(mfr.result_type.clone()),
                    diagnostics: tier0.kernel_diagnostics.clone(),
                })
            }
            None => match crate::v1_compiler_infer_service::check_service_method_call_node(
                receiver_type.clone(),
                method_name.clone(),
                service_registry.clone(),
                source_indices.clone(),
            ) {
                Some(svc_result) => Rc::new(KnownMethodResolution {
                    semantics: Some(Rc::new(MethodSemantics::ServiceMethodSemantics {
                        service_name: crate::v1_std_core::authored_name_at(
                            source_indices.clone(),
                            receiver_type.clone(),
                        ),
                        op_params: svc_result.op_params.clone(),
                    })),
                    result_type: Some(svc_result.result_type.clone()),
                    diagnostics: tier0.kernel_diagnostics.clone(),
                }),
                None => Rc::new(KnownMethodResolution {
                    semantics: None,
                    result_type: None,
                    diagnostics: tier0.kernel_diagnostics.clone(),
                }),
            },
        }
    }
}
